/**
 * Zero schema for the harness DB (`papercusp`).
 *
 * Mirrors the publication `zero_harness`. The harness DB uses the
 * "schema-per-harness" layout (Option B) — each harness has its own
 * `harness_<slug>.harness_features` + `harness_<slug>.feature_audit`,
 * plus cross-cutting tables in `harness_shared` and `papercup_shared`.
 *
 * This file currently covers the cross-cutting (non-per-harness) tables.
 * Per-harness tables (`harness_features`, `feature_audit`) are deferred
 * pending a decision on whether to expose them via a UNION view in
 * `harness_shared` or via per-slug Zero tables.
 *
 * Timestamps are number() (epoch ms). bigint columns in PG are emitted by
 * zero-cache as numbers — match the existing libs/zero convention.
 *
 * Use `.from('schema.table')` to map the client-side table key to the
 * schema-qualified PG/replica name (verified working with WS).
 */
import {
  createBuilder,
  createSchema,
  type Row,
  table,
  string,
  number,
  boolean,
  json,
  type ReadonlyJSONValue,
} from '@rocicorp/zero';

// ── harness_shared.projects ──────────────────────────────────────────────
export const projects = table('projects')
  .from('harness_shared.projects')
  .columns({
    id: string(),
    name: string(),
    status: string(),
    slug: string().optional(),
    budgetCents: number().optional().from('budget_cents'),
    spentCents: number().from('spent_cents'),
    costCapCents: number().optional().from('cost_cap_cents'),
    earnedCents: number().from('earned_cents'),
    owningDept: string().optional().from('owning_dept'),
    vertical: string().optional(),
    createdTs: number().from('created_ts'),
    updatedTs: number().from('updated_ts'),
    metadata: json<ReadonlyJSONValue>().optional(),
  })
  .primaryKey('id');

