// ── Per-harness features tables ───────────────────────────────────────────
// PG views can't be in logical-replication publications, so each harness's
// `harness_<slug>.harness_features` is its own table in this schema. The
// list below mirrors the schemas that exist in the database. When a new
// harness is created, add its slug here AND ensure the publication has the
// table (`ALTER PUBLICATION zero_harness ADD TABLE harness_<slug>.harness_features`).
const HARNESS_SLUGS = [
  'sheets',
  'org',
  'org_business',
  'org_coordination',
  'org_management',
  'org_marketing',
  'org_rd',
  'org_technology',
  'restart',
] as const;

type HarnessSlug = typeof HARNESS_SLUGS[number];

function harnessFeaturesTable(slug: HarnessSlug) {
  // Camel-case the table key (used for `zql.<key>`) but keep the PG
  // mapping schema-qualified.
  const key =
    'features' +
    slug
      .split('_')
      .map((p) => p[0].toUpperCase() + p.slice(1))
      .join('');
  return table(key)
    .from(`harness_${slug}.harness_features`)
    .columns({
      harnessSlug: string().from('harness_slug'),
      featureId: string().from('feature_id'),
      title: string(),
      summary: string().optional(),
      status: string(),
      attempts: number(),
      claims: string().optional(),
      notes: string().optional(),
      metadata: json<ReadonlyJSONValue>().optional(),
      kind: string().optional(),
      projectId: string().optional().from('project_id'),
      expectedCostCents: number().optional().from('expected_cost_cents'),
      tags: json<ReadonlyJSONValue>().optional(),
      needsHumanReview: boolean().from('needs_human_review'),
      ts: number().optional(),
      createdTs: number().from('created_ts'),
      updatedTs: number().from('updated_ts'),
      parentId: string().optional().from('parent_id'),
      goalId: string().optional().from('goal_id'),
      takenBy: string().optional().from('taken_by'),
    })
    .primaryKey('harnessSlug', 'featureId');
}

