// ── Per-harness issues tables ────────────────────────────────────────────
// Same pattern as featuresXxx: PG views can't replicate, so each harness
// gets its own `harness_<slug>.harness_issues` table in the schema.
function harnessIssuesTable(slug: HarnessSlug) {
  const key =
    'issues' +
    slug
      .split('_')
      .map((p) => p[0].toUpperCase() + p.slice(1))
      .join('');
  return table(key)
    .from(`harness_${slug}.harness_issues`)
    .columns({
      harnessSlug: string().from('harness_slug'),
      issueId: string().from('issue_id'),
      title: string(),
      severity: string(),
      source: string(),
      status: string(),
      foundAt: number().from('found_at'),
      foundDuring: string().optional().from('found_during'),
      repro: string().optional(),
      evidence: string().optional(),
      suggestedFix: string().optional().from('suggested_fix'),
      codePointer: string().optional().from('code_pointer'),
      linkedFeatureId: string().optional().from('linked_feature_id'),
      attempts: number(),
      notes: json<ReadonlyJSONValue>(),
      createdTs: number().from('created_ts'),
      updatedTs: number().from('updated_ts'),
    })
    .primaryKey('harnessSlug', 'issueId');
}

